// Read-only; does not reveal API keys or send inference requests.
console.log(await suggestionGrader.getSettings());
console.log(await suggestionGrader.help());

const uri = ''; // Fill in the resolved local:// notebook URI.
const cellId = ''; // Fill in the target cell refId.
const newText = ''; // Fill in the replacement source.
if (!uri || !cellId) throw new Error('Set uri, cellId and newText before running.');
if (!(await notebooks.help('update')).includes('grade?: boolean')) throw new Error('This build does not support graded updates.');
const target = { uri };
const doc = await notebooks.get(target);
const updated = await notebooks.update({
  target,
  expectedRevision: doc.handle.revision,
  operations: [{ op: 'update', refId: cellId, patch: { value: newText } }],
  grade: true,
});
console.log({ handle: updated.handle, grading: updated.grading });
